## 사용 방법

통신 방법은 `Moya`와 비슷합니다. 

우선, API를 작정해, 수행할 Task들을 `enum`으로 정의합니다. 
```Swift 
enum UserAPI {
	case getUserList
	case postUser
}
```
이후, TargetType을 채택해 Moya와 같이 사용합니다. 

```Swift 
extension UserAPI: TargetType {
	var baseURL: URL {
		URL(string: "https://koreanjson.com")!
	}
	
	var path: String {
		switch self {
			case .getUserList:
				return "users"
			case .postUser:
				return "users"
		}
	}
	
	var method: HTTPMethod {
		switch self {
			case .getUserList:
				return .get
			case .postUser:
				return .post
		}
	}
	
	var task: TaskType {
		...
	}
	
	var headers: HTTPHeaders {
		.init()
	}
	
	var sampleResponse: EndpointSampleResponse {
		switch self {
			case .getUserList:
				return .networkResponse(200, Data())
			case .postUser:
				return .networkResponse(200, Data())
		}
	}
}
```
### Task Type

`TaskType`은 다음과 같이 제공됩니다. 
```Swift 
public enum TaskType {
  /// 추가적인 Data없이 request를 합니다.
  case requestPlain
  /// request body에 파라미터로 전달된 `Data`타입을 저장합니다.
  case requestData(Data)
  /// request body에 `Encodable`을 json 형태로 저장합니다.
  case requestJSONEncodable(Encodable)
  /// request body에 `Encodable`을  custom encoder를 통해 저장합니다.
  case requestCustomJSONEncodable(Encodable, encoder: JSONEncoder)
  /// request에 `parameters`를 저장합니다. `encoding`을 통해 URL인지 JSON인지 결정할 수 있습니다.
  case requestParameters(parameters: [String: Any], encoding: ParameterEncoding)
  /// request body에 data를 저장하고, , `urlParameters`를 저장합니다.
  case requestCompositeData(bodyData: Data, urlParameters: [String: Any])
  /// request body에 `bodyParameters`를 저장하고, `urlParameters`를 저장합니다.
  case requestCompositeParameters(bodyParameters: [String: Any], urlParameters: [String: Any])
  /// "multipart/form-data"를 upload합니다.
  case uploadMultipartFormData(multipart: MultipartFormData)
}
```
`MultipartFormData`의 경우에는 다음과 같이 구성합니다. 
- 필요한 mimeType & fileExtension 별로 `bodyParts`를 생성합니다. 
- 이후, `MultipartFormData`를 생성시 `bodyParts`를 파라미터로 전달합니다. 
```Swift 
var task: TaskType {
	switch self {
		case .getUserList:
			return .requestPlain
			
		case let .uploadUser(dto)
			let parameter = dto.toDictionary(excludeKey: "profileImage", "someImage")
			let imageParameter = dto.toDictionary(includeKey: "profileImage", "someImage")

			let parameterBody = MultipartFormDataBodyPart(.parameters(parameter))
			let imageBody = MultipartFormDataBodyPart(
				.data(imageParameter),
				fileExtension: "png",
				mimeType: "image/png"
			)

			let multiPart = MultipartFormData(bodyParts: [parameterBody, imageBody])

			return .uploadMultipartFormData(multipart: multiPart)
	}
}

```

### Provider
`StubBehavior`를 통해 실제 통신과, 가짜 통신을 구별합니다. 
이때, 가짜 통신은 즉시 리턴하는 `immediate`와 `seconds`초 이후에 리턴하는 `delayed`가 존재합니다.
```Swift 
public enum StubBehavior {
	/// stub가 아닌 실제 서버와 통신합니다.
	case never
	/// stub 데이터를 즉시 리턴합니다.
	case immediate
	/// stub 데이터를 `seconds` 이후에 리턴합니다.
	case delayed(seconds: TimeInterval)
}
```

이후, `Provider`를 통해 API를 호출합니다.
```Swift 
struct Repository {
	func fetchUser() -> Single<[UserResponseDTO]> {
		return Provider(stubBehavior: .immediate)
			.request(UserAPI.getUserList, type: [UserResponseDTO].self)
			.map { baseResponse in
				print("status: \(baseResponse.statusCode)")
				print("base: \(baseResponse.data)")
				
				return baseResponse.data
			}
	}
}
```

